"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["1429"],{6786(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>o,contentTitle:()=>s,toc:()=>l,assets:()=>h});var n=JSON.parse('{"id":"Setting/Rithmia/Worldwide Factions/cult-of-the-unspeakable","title":"Cult of the Unspeakable","description":"This is a cult of mostly wealthy and powerful nihilists. They believe nothing has meaning but the King promises that there is meaning in the universe. A person\'s base carnal desires whatever sin they embody most is their true purpose. Once all the world realizes what is going on the King will allow them to join his kingdom. They are preparing the symphony of madness. A subtle song that once it reaches a person\'s ears it turn on their sleeper agent serum they begin to lose control and act purely on instinct. Turning them into horrid aberrant thralls physically as well. Once this melody starts the countdown begins to the King absorbs them into his \\"kingdom\\".","source":"@site/docs/Setting/Rithmia/Worldwide Factions/cult-of-the-unspeakable.md","sourceDirName":"Setting/Rithmia/Worldwide Factions","slug":"/Setting/Rithmia/Worldwide Factions/cult-of-the-unspeakable","permalink":"/Rithmia/docs/Setting/Rithmia/Worldwide Factions/cult-of-the-unspeakable","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Setting/Rithmia/Worldwide Factions/cult-of-the-unspeakable.md","tags":[],"version":"current","frontMatter":{},"sidebar":"settingSidebar","previous":{"title":"Features of the ocean","permalink":"/Rithmia/docs/Setting/Rithmia/Other Areas/Oceans/features"},"next":{"title":"The Eunsur","permalink":"/Rithmia/docs/Setting/Rithmia/Worldwide Factions/eun\'sur"}}'),r=a(4848),i=a(8453);let o={},s="Cult of the Unspeakable",h={},l=[{value:"Goals",id:"goals",level:2},{value:"Symphony of Madness",id:"symphony-of-madness",level:2},{value:"Members",id:"members",level:2},{value:"Public facing Offshoot - The Theatrum Aeternum",id:"public-facing-offshoot---the-theatrum-aeternum",level:2},{value:"d4 NPC",id:"d4-npc",level:3},{value:"d6 Adventure Hooks",id:"d6-adventure-hooks",level:3},{value:"Importants Items",id:"importants-items",level:2}];function d(e){let t={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"cult-of-the-unspeakable",children:"Cult of the Unspeakable"})}),"\n",(0,r.jsx)(t.p,{children:"This is a cult of mostly wealthy and powerful nihilists. They believe nothing has meaning but the King promises that there is meaning in the universe. A person's base carnal desires whatever sin they embody most is their true purpose. Once all the world realizes what is going on the King will allow them to join his kingdom. They are preparing the symphony of madness. A subtle song that once it reaches a person's ears it turn on their sleeper agent serum they begin to lose control and act purely on instinct. Turning them into horrid aberrant thralls physically as well. Once this melody starts the countdown begins to the King absorbs them into his \"kingdom\"."}),"\n",(0,r.jsx)(t.p,{children:(0,r.jsx)(t.a,{href:"https://anyflip.com/prknn/uizr/basic",children:"https://anyflip.com/prknn/uizr/basic"})}),"\n",(0,r.jsx)(t.p,{children:(0,r.jsx)(t.a,{href:"https://anyflip.com/homepage/prknn",children:"https://anyflip.com/homepage/prknn"})}),"\n",(0,r.jsx)(t.p,{children:"The scourge (my flood) were released pre current history and Yith'zizctal was the leader they referred to as the eldest and is one science project the unspeakable used to see if there was a way for him to spread influence and absorb life forms in areas where the purple light did not reach."}),"\n",(0,r.jsx)(t.p,{children:"There are those corrupted by the unspeakable as its power  is greater over this planet"}),"\n",(0,r.jsx)(t.p,{children:"The cult is a group of those who have been corrupted by staved off madness by consuing knowledge and have found a lost offspring of their god is imprisoned by the gods in the core of Rithmia and they intend to awaken it."}),"\n",(0,r.jsx)(t.p,{children:"The symphony of madness is an event where worldwide sounds at specific frequencies will be rippling throughout the material plane and the amplification of an eclipse will cause the overlapping of vibration and magical energy to open portals to different realms."}),"\n",(0,r.jsx)(t.p,{children:"Yith\u2019Zizctal, the scourge, and the symphony of madness are three servants to the Unspeakable all working towards its goal of complete corruption. It is a being of pure nihilism, and entropy and yearns for the eventual day when all life is a part of it."}),"\n",(0,r.jsx)(t.h2,{id:"goals",children:"Goals"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsx)(t.li,{children:"Release Yith'Zizctal"}),"\n",(0,r.jsx)(t.li,{children:"Start symphony of madness"}),"\n",(0,r.jsx)(t.li,{children:"Find the Key of the Stars to unlock a Gate to Xxiphu and allow The Unspeakable to enter the material plane. Opens a portal to the far realm to let the voidspawn in. But is a two way portal between the prime material plane and a planet that directly orbits a purple star."}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"To release Yith\u2019Zizctal a sphere of annihilation must be placed inside the core of each pillar of restraint. According to legend Gaia the earth mother whose body made Rithmia split herself open and \u201Dremoved her heart\u201D then Caldor the iron lord plunged Yith\u2019Zizctal into the center of the world where According to legend Xintris the weaver comprised a powerful seal digit over the world wrapping around the pillars of restraint however they did not do this alone. Asmosdeus was the final one to lock and sealed the all consumer away keeping the only key constantly on his person."}),"\n",(0,r.jsx)(t.p,{children:"Caldors greatsword shattered into over a dozen smaller shards of \u201Cgod metal\u201D which are forged into artifacts resembling holy avengers."}),"\n",(0,r.jsx)(t.p,{children:"This left Gaia fractured into herself and zuggtmoy"}),"\n",(0,r.jsx)(t.p,{children:"This had unintended consequences on arcane magic. Since the pillars were originally built to contain powerful being mainly of arcane power Yith\u2019Zizctal seems to be able to consume arcane power and the weave itself. Slowly the power of the weave will weaken until Yith\u2019Zizctal is able to draw on this power decreasing the power of arcane casters. In its prison it is unable to consume constantly and once a millennia can draw power from all spellcasters decreasing the slots of their highest level by one meaning no 9th level spells can be cast."}),"\n",(0,r.jsx)(t.p,{children:"Nobody knows why Asmodeus protected the material plane he had grown hateful of. Nobody knows what Asmodeus gained or lost in this deal."}),"\n",(0,r.jsx)(t.p,{children:'Ziesis, The Reaper, God of necromancy "stitched" the slash the created a crevice in Rithmia but he sewed a nexus point with a strong connection to the shadowfell and all other lower planes.'}),"\n",(0,r.jsx)(t.p,{children:'Yith\'Zizctal is said to have "consumed all parts of a deity",  all records, memories of everything about it down to its name have disappeared.'}),"\n",(0,r.jsx)(t.h2,{id:"symphony-of-madness",children:"Symphony of Madness"}),"\n",(0,r.jsx)(t.p,{children:"This symphony has two parts."}),"\n",(0,r.jsx)(t.p,{children:"First it is literally a melody that spreads all around the world sewing madness into all parts of the world."}),"\n",(0,r.jsx)(t.p,{children:"Second the resonance of the above song causes leylines and other planar nexus's to shift and tear into portals to the far realm where the army of the unspeakable waits to consume."}),"\n",(0,r.jsx)(t.h2,{id:"members",children:"Members"}),"\n",(0,r.jsx)(t.p,{children:"1 Eldritch Lich\r\nStar spawn seers\r\nNobles\r\nArchmages\r\nTyrants/Warlords\r\nWealthy Bards\r\nThe churning (actually on the continent of Ikothon)\r\nEldritch Heralds & Eldritch priests from pathfinder\r\nThe fractured (pathfinder)\r\nParasite warlock\r\nBlightworm warlock, ascendant\r\nBlightworm"}),"\n",(0,r.jsx)(t.h2,{id:"public-facing-offshoot---the-theatrum-aeternum",children:"Public facing Offshoot - The Theatrum Aeternum"}),"\n",(0,r.jsx)(t.p,{children:"Founded by Valdemar de Iseni, The Theatrum Aeternum, or \u201CEternal Theatre,\u201D is an internationally renowned theatrical company known for operating theaters and traveling shows worldwide and even on other planes of existence. The Theatrum has earned its acclaim and influence through the recruitment and training of those who perform to the highest degree of excellence in their trade; Theatre is the \u201Call-inclusive art,\u201D and the Theatrum thrives on this principle - recruiting singers, dancers, actors, writers, artists, strongmen, magicians, acrobats, duelists, and scholars. All these and more help to make the Theatrum\u2019s performances excel beyond the scope and quality of lesser pretenders and reach into spheres of influence ranging from yeomen taverns to royal halls to the courts of devil dukes."}),"\n",(0,r.jsx)(t.p,{children:"Perceptions of the Theatrum range from casual dismissal, joyous fanaticism, awe, and fear, depending on the character of a local director and their company. But all pay homage to the legacy of Valdemar, whose genius, talent, and toil laid the foundations for the company to expand ever outward in the following decades and centuries."}),"\n",(0,r.jsx)(t.p,{children:"Only a few individuals know that Valdemar continues to guide and direct the company from the shadows. Valdemar has harnessed the success of his legacy through a unique variation of lich-craft, becoming a playwright lich. By entwining his soul with the plays and legacy of the Theatrum, Valdemar has ensured his unlife so long as the company continues to perform his plays. Valdemar ensures this through contracts with companies licensed with the Theatrum - often to the detriment of new artists trying to gain exposure for new, original work."}),"\n",(0,r.jsx)(t.p,{children:"Theatrum Aeternum NPCs"}),"\n",(0,r.jsx)(t.p,{children:"Most of the Theatrum\u2019s members are artists of some kind - builders, painters, singers, dancers, actors, writers, and more contribute their talents to each company\u2019s spectacles. The Theatrum also draws the attention of merchants and nobles who may act as patrons for individual artists or share their favor with a company. Certain theaters, however, regularly push the boundaries of spectacle to awe their audiences, employing magicians and warriors to display legendary feats of swordplay, spell, and skilcraft."}),"\n",(0,r.jsx)(t.p,{children:"Any mage can earn an impressive wage with the Theatrum using anything from simple illusions to gravity-defying spells to enhance the performance of a group of dancers, legendary thieves and rakes often put acrobats with formal training to shame, and in particularly daring shows, swordsmen and warriors may battle a captured or summoned monstrosity for the audience\u2019s enjoyment, harkening to gladiatorial contests. Advertising the inclusion of a famous or infamous adventurer in a show\u2019s cast may also draw crowds of that individual\u2019s supporters and detractors. Since becoming a multi-planar organization, the Theatrum has accrued a wealth of knowledge, attracting scholars and even residents and creatures from other planes to join the Theatrum."}),"\n",(0,r.jsx)(t.h3,{id:"d4-npc",children:"d4 NPC"}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsx)(t.li,{children:"A young playwright seeking inspiration for their next play asks the player characters about their adventures and asks to join them on their next outing."}),"\n",(0,r.jsx)(t.li,{children:"A senior performer who jealously guards against upstarts that threaten to dethrone them as a leading star."}),"\n",(0,r.jsx)(t.li,{children:"An obsessed fan of one of the company\u2019s performers, who constantly attempts to secure time with the object of their obsession and collect \u201Ckeepsakes\u201D of their idol."}),"\n",(0,r.jsx)(t.li,{children:"A director, weary of the company\u2019s recent shows, wants to re-enliven and challenge their audience by introducing a \u201Chint of true danger\u201D by incorporating a captured monster into the next performance."}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"Theatrum Aeternum Campaign Themes"}),"\n",(0,r.jsx)(t.p,{children:"A Theatrum Aeternum campaign explores themes of intrigue, creative and personal freedom, and what price is too high to create art.\u202F\u202F It is quite possible for the Theatrum to be an antagonistic or friendly faction for a party of adventurers from quest to quest, as different regional directors and their companies will adopt unique practices to achieve the faction\u2019s overall goal to spread the influence of the Theatrum. Political allies and adversaries may well be invested in the Theatrum\u2019s success or failure, and rivalries frequently develop between actors, writers, and artists, ranging from friendly competition to deadly sabotage and assassination."}),"\n",(0,r.jsx)(t.p,{children:"Faction Adventure Hooks"}),"\n",(0,r.jsx)(t.p,{children:"The Theatrum Aeternum Adventure Hooks table suggests a variety of ideas for drawing the party into the glamorous world of the Eternal Theatre."}),"\n",(0,r.jsx)(t.p,{children:"Faction Adventure Hooks Table"}),"\n",(0,r.jsx)(t.h3,{id:"d6-adventure-hooks",children:"d6 Adventure Hooks"}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsx)(t.li,{children:"Patrons of a small town Theatrum subsidiary have lost their valuables during their most recent shows. The theater director hires the party to put a stop to the apparent pickpocketing so that audiences can attend the shows without fear of theft."}),"\n",(0,r.jsx)(t.li,{children:"When members of a company die from apparent stage accidents, one of the crew members reaches out to the party, fearful that a murderer is stalking the company, or that a curse has befallen them. Can the party find the cause and bring it to an end before the rest of the company falls victim?"}),"\n",(0,r.jsx)(t.li,{children:"An independent company of performers have been rising in fame and fortune among audiences, but they have received threats ordering them to shut down their theater. They reach out to the party to hire them as protection during their grand opening. What no one yet knows is that the Eternal Theatre is behind the threats, and they have more than just hired assassins and saboteurs at their disposal."}),"\n",(0,r.jsx)(t.li,{children:"The spirit of a deceased actor appears during a show, threatening to throw off the performance. Can the party put an end to the spirit\u2019s impromptu performances? And can they discover what has disturbed their rest?"}),"\n",(0,r.jsx)(t.li,{children:"Mad Molly, director of the Multiversal Muster Subsidiary Company, has received an invitation from Duke Inferi of the lower planes to perform in his court. This show calls for performers who are no strangers to violence, as the devilish audience members frequently participate in the show!"}),"\n",(0,r.jsx)(t.li,{children:"The Theatrum advertises a \u201Cmillennia defining\u201D event - the performance of a powerful magical ritual in the form of a play. Rumors abound as to what will result from completing the play, and its ritual; Will it grant apotheosis to one of its actors? Open a sealed gateway? Summon a powerful being? Grant a wish? If true, the completion of this play before an audience could change the face of the world, and the party must decide if, and how, they will get involved."}),"\n"]}),"\n",(0,r.jsxs)(t.p,{children:["From ",(0,r.jsx)(t.a,{href:"https://www.thedmlair.com/2023/03/20/free-rpg-faction-the-theatrum-aeternum/",children:"DM Lair Free RPG Faction The Theatrum Aeternum"})]}),"\n",(0,r.jsx)(t.h2,{id:"importants-items",children:"Importants Items"}),"\n",(0,r.jsxs)(t.p,{children:["Black crystal tablet ",(0,r.jsx)(t.a,{href:"http://longo.com.br/5e/items.html#black%20crystal%20tablet_wdmm",children:"http://longo.com.br/5e/items.html#black%20crystal%20tablet_wdmm"}),"\u202F\r\nFar realm shards ",(0,r.jsx)(t.a,{href:"http://dnd5e.wikidot.com/wondrous-items:far-realm-shard",children:"http://dnd5e.wikidot.com/wondrous-items:far-realm-shard"}),"\u202F\r\nHammock of worlds ",(0,r.jsx)(t.a,{href:"http://dnd5e.wikidot.com/wondrous-items:hammock-of-worlds",children:"http://dnd5e.wikidot.com/wondrous-items:hammock-of-worlds"}),"\r\nSphere of Annihilation"]})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,t,a){a.d(t,{R:()=>o,x:()=>s});var n=a(6540);let r={},i=n.createContext(r);function o(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);